/** Hide citations generated by older versions without removing catalog links or player notes. */
export function withoutSrdPageReferences(text: string) {
  return text
    .replace(/SRD 5\.2\.1, PDF pp?\.\s*[\d–-]+; catalog:/g, 'SRD 5.2.1; catalog:')
    .replace(
      /SRD 5\.2\.1 PDF pp\.[\d,–-]+; individual source classes\/backgrounds in catalog\./g,
      'Individual source classes and backgrounds are in the SRD catalog.',
    )
    .replace(
      /Starting grant\/purchase: SRD 5\.2\.1 class p\.\d+, background p\.\d+\. Pack contents are individually expanded from PDF pp\.[\d–-]+\./g,
      'Starting grant or purchase. Pack contents are listed individually.',
    )
    .replace(/ See PDF p\.\d+\./g, '')
    .replace(/ \(p\.78\)(?=; package A already includes it)/g, '')
    .replace(/ (?:SRD 5\.2\.1|SRD) p\.\s*\d+\./g, '');
}

export const srdCatalogCitation = /\n\nSRD 5\.2\.1; catalog: ([\w-]+)\./;
